from mk import *
from lib import fbd
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 330, "מסילה חלקה AB על שולחן בגובה H: הקצה A בגובה h מעל השולחן, והקצה B אופקי בקצה השולחן. כדור נורה מ-A במורד המסילה במהירות v0 ונוחת במרחק x. וגרף x בריבוע כפונקציה של h: קו ישר מ-1 ב-h=0 עד 11 ב-h=2 מטר. תרשים ג (סעיף ה): כדור שני מוחזק בגובה H מעל הקרקע, במרחק 1.5 מטר מקצה השולחן")
    g.ground(20, 300, 150); g.rect(120, 92, 170, 10, fill="var(--d-fill)"); g.line(140, 102, 140, 150, width=3); g.line(270, 102, 270, 150, width=3)
    g.path("M 130,90 Q 220,90 280,24", width=2.5); g.line(280, 24, 280, 90, stroke="var(--d-dim)", width=1, dash="3 3")
    g.ball(266, 34, 5); g.arrow(258, 42, 236, 58, "v₀", lx=240, ly=40)
    g.text(288, 22, "A", anchor="start"); g.text(126, 84, "B", anchor="end")
    g.dim(296, 24, 296, 92, "h", offset=0); g.dim(296, 102, 296, 150, "H", offset=0)
    g.path("M 128,90 Q 80,92 50,148", stroke="var(--d-dim)", width=1.4, dash="5 4"); g.dim(50, 165, 140, 165, "x", offset=0)
    g.heb(160, 186, "תרשים א")
    # תרשים ג (part ה): the second ball, at height H, 1.5 m from the table's edge
    gy = 300; g.ground(20, 300, gy); g.rect(140, gy - 48, 150, 8, fill="var(--d-fill)"); g.line(160, gy - 40, 160, gy, width=3); g.line(270, gy - 40, 270, gy, width=3)
    g.path(f"M 150,{gy - 50} Q 230,{gy - 50} 280,{gy - 94}", width=2.2); g.dim(296, gy - 94, 296, gy - 48, "0.5 m", offset=0)
    g.ball(60, gy - 48, 6); g.line(60, gy - 42, 60, gy, stroke="var(--d-dim)", width=1, dash="3 3"); g.dim(60, gy - 64, 140, gy - 64, "1.5 m", offset=0)
    g.heb(160, gy + 24, "תרשים ג")
    X, Y = g.graph(350, 270, 180, 200, "h (m)", "x² (m²)", xticks=[(v, f"{v:g}") for v in (0.5, 1, 1.5, 2, 2.5)], yticks=[(v, str(v)) for v in (2, 4, 6, 8, 10, 12)], xmax=2.5, ymax=12)
    g.plot(X, Y, [(0, 1), (2, 11)])
    return g

vB = math.sqrt(4 + 2 * 10 * 0.5); t1 = 1.5 / vB; tf = math.sqrt(2 * 1.25 / 10)
E(id="bagrut-2012-q3", year=2012, label="2012 שאלה 3", topic="energy", sub="en-conservation", diff=4, fig=fig,
  stem=r"אורי מחבר מסילה חלקה $AB$ לשולחן שגובהו $H$. הקצה התחתון של המסילה אופקי, ונמצא בדיוק בקצה השולחן. אורי \"יורה\" כדור קטן במורד המסילה, במהירות התחלתית $v_0$ בכיוון המסילה. הכדור נע על המסילה עד קצה השולחן, $B$, ממשיך באוויר ופוגע ברצפה. אורי מודד את המרחק האופקי $x$ מקצה השולחן עד נקודת הפגיעה. הוא חוזר על הניסוי כמה פעמים, ובכל פעם משנה את הגובה $h$ שממנו הוא יורה את הכדור, אבל גודל המהירות ההתחלתית $v_0$ נשאר קבוע. הגרף מראה את $x^2$ כפונקציה של $h$.",
  parts=[
    P("א", r"הוכיחו שהקשר בין $x^2$ לגובה $h$ מעל השולחן הוא $x^2 = \frac{2H}{g}v_0^2 + 4Hh$.", OPEN, ["principle", "algebra"], [
        S(r"המהירות בנקודה B", r"המסילה חלקה, ולכן האנרגיה המכנית נשמרת. המסה מצטמצמת", r"\tfrac{1}{2}m\,v_0^2 + m g h = \tfrac{1}{2}m\,v_B^2 \;\Rightarrow\; v_B^2 = v_0^2 + 2gh", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"זמן הנפילה", r"הכדור עוזב את השולחן אופקית, ולכן בציר האנכי הוא יוצא בלי מהירות", r"H = \tfrac{1}{2}g t^2 \;\Rightarrow\; t^2 = \frac{2H}{g}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"המרחק", r"בציר האופקי המהירות קבועה. מעלים בריבוע ומציבים", r"x^2 = v_B^2\,t^2 = (v_0^2 + 2gh)\,\frac{2H}{g} = \frac{2H}{g}v_0^2 + 4Hh"),
    ], r"$x^2 = (v_0^2 + 2gh)\frac{2H}{g} = \frac{2H}{g}v_0^2 + 4Hh$"),
    P("ב", r"הסבירו למה $4H$ הוא השיפוע של הגרף.", OPEN, ["graph"], [
        S(r"קו ישר", r"הביטוי הוא קו ישר כשהגובה הוא המשתנה. האיבר הראשון קבוע, והמספר שמכפיל את הגובה הוא השיפוע", r"x^2 = 4H \cdot h + \frac{2H}{g}v_0^2"),
    ], r"הוא המספר שמכפיל את $h$ בביטוי של הקו הישר"),
    P("ג", r"מה גובה השולחן $H$?", num(1.25, "m"), ["graph"], [
        S(r"שיפוע הגרף", r"בוחרים שתי נקודות על הקו", r"\frac{11 - 1}{2 - 0} = 5\,\text{m}"),
        S(r"הגובה", r"השיפוע שווה לארבע פעמים גובה השולחן", r"4H = 5 \;\Rightarrow\; H = 1.25\,\text{m}"),
    ], r"$1.25\,\text{m}$", key=r"H=1.25 m"),
    P("ד", r"מה גודל המהירות ההתחלתית $v_0$?", num(2, "m/s"), ["graph", "algebra"], [
        S(r"החיתוך עם הציר האנכי", r"כשהגובה אפס נשאר רק האיבר הקבוע. קוראים אותו בגרף", r"\frac{2 \cdot 1.25}{10}\,v_0^2 = 1 \;\Rightarrow\; 0.25\,v_0^2 = 1"),
        S(r"פותרים", r"מוציאים שורש", r"v_0 = \sqrt{4} = 2\,\text{m/s}"),
    ], r"$2\,\text{m/s}$", key=r"v0=2 m/s"),
    P("ה", r"בניסוי אחד הגובה היה $h = 0.5\,\text{m}$. ברגע שהכדור עזב את קצה המסילה, אורי שחרר ממנוחה כדור שני, מגובה $H$ מעל הקרקע ובמרחק אופקי $1.5\,\text{m}$ מקצה השולחן (תרשים ג). הוכיחו שהכדורים ייפגשו לפני שיפגעו בקרקע.", OPEN, ["principle", "algebra"], [
        S(r"המהירות של הכדור הראשון בנקודה B", r"מהביטוי מסעיף א", r"v_B = \sqrt{2^2 + 2 \cdot 10 \cdot 0.5} = \sqrt{14} \approx 3.74\,\text{m/s}"),
        S(r"הזמן עד הקו האנכי של הכדור השני", r"בציר האופקי המהירות קבועה", r"t_1 = \frac{1.5}{3.74} \approx 0.40\,\text{s}"),
        S(r"התנועה האנכית זהה", r"שני הכדורים יוצאים מאותו גובה, בלי מהירות אנכית, באותו רגע ובאותה תאוצה. לכן הם תמיד באותו גובה", r"y_1(t) = y_2(t) = H - \tfrac{1}{2}g t^2"),
        S(r"האם הם עוד באוויר", r"זמן הנפילה מגובה השולחן ארוך מהזמן שהכדור הראשון צריך", r"t_f = \sqrt{\frac{2 \cdot 1.25}{10}} = 0.5\,\text{s} > 0.40\,\text{s}"),
    ], r"הכדורים תמיד באותו גובה, והראשון מגיע לקו של השני אחרי $0.4\,\text{s}$, לפני הנחיתה אחרי $0.5\,\text{s}$"),
  ],
  concepts=["שימור אנרגיה", "זריקה אופקית", "לינאריזציה", "שיפוע וחיתוך", "מפגש"],
  summary=r"כדור שנורה במורד מסילה ועף מהשולחן: מהגרף של ריבוע המרחק מול הגובה מוצאים את גובה השולחן ואת המהירות ההתחלתית.",
  review="הנחה שלי.\nמה לבדוק: רק לאשר.")
